// The query executed by WorkloadVulnerabilityFindings.
const WorkloadVulnerabilityFindings_Operation = `
query WorkloadVulnerabilityFindings ($team: Slug!, $environment: String!, $name: String!, $application: Boolean!, $job: Boolean!, $filter: WorkloadVulnerabilityFindingsFilter!, $order: VulnerabilityFindingOrder, $after: Cursor) {
	team(slug: $team) {
		environment(name: $environment) {
			application(name: $name) @include(if: $application) {
				... WorkloadVulnerabilityFindingPage
			}
			job(name: $name) @include(if: $job) {
				... WorkloadVulnerabilityFindingPage
			}
		}
	}
}
fragment WorkloadVulnerabilityFindingPage on Workload {
	image {
		name
		tag
		digest
	}
	... VulnerabilityWorkloadIdentity
	vulnerabilityFindings(first: 200, after: $after, filter: $filter, orderBy: $order) {
		nodes {
			... VulnerabilityReportFinding
		}
		pageInfo {
			... VulnerabilityPage
		}
	}
}
fragment VulnerabilityWorkloadIdentity on Workload {
	id
	__typename
	name
	team {
		slug
	}
	teamEnvironment {
		environment {
			name
		}
	}
}
fragment VulnerabilityReportFinding on VulnerabilityFinding {
	... VulnerabilityFindingDetails
	suppression {
		reason
	}
}
fragment VulnerabilityPage on PageInfo {
	hasNextPage
	endCursor
}
fragment VulnerabilityFindingDetails on VulnerabilityFinding {
	id
	vulnerabilityIdentifier
	purl
	packageKey
	installedVersion
	fixedVersion
	severity
	severitySource
	dataSource
	knownExploited
	epss {
		... VulnerabilityEpssDetails
	}
	vulnerability {
		... VulnerabilityAdvisory
	}
	suppression {
		state
	}
	image {
		name
		digest
	}
	workload {
		__typename
		... VulnerabilityWorkloadIdentity
	}
}
fragment VulnerabilityEpssDetails on VulnerabilityEpss {
	score
	date
}
fragment VulnerabilityAdvisory on Vulnerability {
	id
	identifier
	aliases
	title
	description
	references
	knownExploited
	epss {
		... VulnerabilityEpssDetails
	}
}
`

